def feature_key(device, metric):
    """生成特征键：不同 (device, metric) 二元组必须对应不同键。"""
    return "{},{}".format(device, metric)

verification_tests:
from target import feature_key

def test_stable_key():
    assert feature_key("d1", "temp") == feature_key("d1", "temp")

def test_distinct_metrics():
    assert feature_key("d1", "temp") != feature_key("d1", "hum")

def test_comma_no_collision():
    assert feature_key("a,b", "m") != feature_key("a", "b,m")
